def solve3(g,bg,wall,thr=2):
    R,C=len(g),len(g[0]); o=[r[:] for r in g]
    w=[(r,c) for r in range(R) for c in range(C) if g[r][c]==wall]
    rm,rx=min(r for r,_ in w),max(r for r,_ in w); cm,cx=min(c for _,c in w),max(c for _,c in w)
    # bbox border fill
    for c in range(cm,cx+1):
        for r in (rm,rx):
            if o[r][c]==bg: o[r][c]=2
    for r in range(rm,rx+1):
        for c in (cm,cx):
            if o[r][c]==bg: o[r][c]=2
    # short gaps anywhere
    for r in range(R):
        xs=[c for c in range(C) if g[r][c]==wall]
        for a,b in zip(xs,xs[1:]):
            if b-a-1<=thr and all(g[r][c]==bg for c in range(a+1,b)):
                for c in range(a+1,b): o[r][c]=2
    for c in range(C):
        ys=[r for r in range(R) if g[r][c]==wall]
        for a,b in zip(ys,ys[1:]):
            if b-a-1<=thr and all(g[r][c]==bg for r in range(a+1,b)):
                for r in range(a+1,b): o[r][c]=2
    return o
