            if o[r][c]==bg: o[r][c]=2
    def runs(seq):
        out=[];i=0;n=len(seq)
        while i<n:
            if seq[i]: j=i
            while j<n and seq[j]: j+=1
            if j-i>=minrun: out.append((i,j-1))
            i=j
        return out
    for r in range(R):
        rowv=[g[r][c]==wall for c in range(C)]
        if any(b-a+1>=minrun for a,b in runs(rowv)):
            xs=[c for c in range(C) if g[r][c]==wall]
            for a,b in zip(xs,xs[1:]):
                if all(g[r][c]==bg for c in range(a+1,b)):
                    for c in range(a+1,b): o[r][c]=2
    for c in range(C):
        colv=[g[r][c]==wall for r in range(R)]
        if any(b-a+1>=minrun for a,b in runs(colv)):
            ys=[r for r in range(R) if g[r][c]==wall]
            for a,b in zip(ys,ys[1:]):
                if all(g[r][c]==bg for r in range(a+1,b)):
                    for r in range(a+1,b): o[r][c]=2
    return o
